def tops(msg: str) -> str:
    n = len(msg)
    if n == 0:
        return ""

    rows = []
    i = 0
    while i < n:
        row_chars = []
        current_i = i
        step = 1
        while current_i < n:
            row_chars.append(msg[current_i])
            current_i += step
            step += 1
        rows.append(row_chars)
        i += 1

    tops_list = []
    for r in range(len(rows)):
        if r < len(rows):
            row = rows[r]
            if row:
                max_char = row[0]
                for c in row[1:]:
                    if c > max_char:
                        max_char = c
                tops_list.append(max_char)

    tops_list.sort(reverse=True)
    return "".join(tops_list)
